# Try various formats
formats = [
    ('rlm.finish', {'summary': 'test'}),
    ('rlm/finish', {'summary': 'test'}),
    ('world.rlm.finish', {'summary': 'test'}),
]
for name, args in formats:
    try:
        r = await world.call(name, **args)
        print(f"{name}: {r}")
    except Exception as e:
        print(f"{name}: ERROR - {e}")
